angular.module('Curve')
  .factory('CwrTerritories', () => {
    // Grouped by continent, includes all territories regardless of CISAC status
    const GROUPED_BY_CONTINENT = {
      Africa: CISAC_COUNTRIES_AFRICA,
      Americas: CISAC_COUNTRIES_AMERICAS,
      Asia: CISAC_COUNTRIES_ASIA,
      Europe: CISAC_COUNTRIES_EUROPE,
      Oceania: CISAC_COUNTRIES_OCEANIA,
    };

    const filterInvalid = (territories) => territories.filter((t) => !t.invalidForCwr);

    // Grouped by continent, excluding non CISAC approved territories
    const GROUPED_BY_CONTINENT_EXCLUDING_NON_CISAC = {
      Africa: filterInvalid(CISAC_COUNTRIES_AFRICA),
      Americas: filterInvalid(CISAC_COUNTRIES_AMERICAS),
      Asia: filterInvalid(CISAC_COUNTRIES_ASIA),
      Europe: filterInvalid(CISAC_COUNTRIES_EUROPE),
      Oceania: filterInvalid(CISAC_COUNTRIES_OCEANIA),
    };

    // Total count of all CISAC territories, 201
    const COUNT = Object.values(GROUPED_BY_CONTINENT_EXCLUDING_NON_CISAC).flat().length;

    const formatForAllList = (list, continent) => list.map((territory) => ({ ...territory, continent }));

    // This list is grouped differently, used in dropdown lists e.g. delivery partner settings
    const ALL = [
      { code: 'WW', name: 'World', continent: 'World' },
      { code: 'Africa', name: 'All Africa', continent: 'Africa' },
      formatForAllList(filterInvalid(CISAC_COUNTRIES_AFRICA), 'Africa'),
      { code: 'Americas', name: 'All Americas', continent: 'Americas' },
      formatForAllList(filterInvalid(CISAC_COUNTRIES_AMERICAS), 'Americas'),
      { code: 'Asia', name: 'All Asia', continent: 'Asia' },
      formatForAllList(filterInvalid(CISAC_COUNTRIES_ASIA), 'Asia'),
      { code: 'Europe', name: 'All Europe', continent: 'Europe' },
      formatForAllList(filterInvalid(CISAC_COUNTRIES_EUROPE), 'Europe'),
      { code: 'Oceania', name: 'All Oceania', continent: 'Oceania' },
      formatForAllList(filterInvalid(CISAC_COUNTRIES_OCEANIA), 'Oceania'),
    ].flat();

    const getInvalidTerritories = (territoryCodes) => {
      const invalid = [];
      for (const code of territoryCodes) {
        const territory = Object.values(GROUPED_BY_CONTINENT).flat().find((t) => t.code === code);
        if (territory.invalidForCwr) invalid.push(territory);
      }
      return invalid;
    };

    const isOnlyInvalidTerritories = (territoryCodes) => {
      if (!territoryCodes || territoryCodes?.length === 0) return false;
      const invalid = getInvalidTerritories(territoryCodes);
      return invalid.length === territoryCodes.length;
    };

    return {
      COUNT,
      GROUPED_BY_CONTINENT,
      GROUPED_BY_CONTINENT_EXCLUDING_NON_CISAC,
      ALL,
      getInvalidTerritories,
      isOnlyInvalidTerritories,
    };
  });
